/*
 * libsrtp configuration for KetPhone, written by hand rather than generated by libsrtp's CMake or
 * configure so that CMake and the Swift package compile exactly the same code: the built-in
 * AES-ICM and HMAC-SHA1 (no OpenSSL, mbedTLS or NSS, hence no AES-GCM) and no debug logging.
 */
#ifndef KETPHONE_LIBSRTP_CONFIG_H
#define KETPHONE_LIBSRTP_CONFIG_H

#define PACKAGE_VERSION "2.7.0"
#define PACKAGE_STRING "libsrtp2 2.7.0"

/* libsrtp's own CMake build sets this on every architecture. */
#define CPU_CISC 1

#if defined(__BYTE_ORDER__) && __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
#define WORDS_BIGENDIAN 1
#endif

#define HAVE_ARPA_INET_H 1
#define HAVE_INTTYPES_H 1
#define HAVE_NETINET_IN_H 1
#define HAVE_STDINT_H 1
#define HAVE_STDLIB_H 1
#define HAVE_SYS_SOCKET_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_UNISTD_H 1
#define HAVE_INET_PTON 1
#define HAVE_UINT8_T 1
#define HAVE_UINT16_T 1
#define HAVE_UINT32_T 1
#define HAVE_UINT64_T 1
#define HAVE_INT32_T 1
#define HAVE_INLINE 1

#define SIZEOF_UNSIGNED_LONG __SIZEOF_LONG__
#define SIZEOF_UNSIGNED_LONG_LONG __SIZEOF_LONG_LONG__

#endif /* KETPHONE_LIBSRTP_CONFIG_H */
